B({ story: {
  /* 11. Шов */
  "11-1": { t: "Последний прямой сеанс", a: "Зоя Кравец",
    x: "— Седьмой, слышу тебя! Ты в Шве? Шумит так, будто рация лежит на дне колодца. — Слышу, Зоя. — Лифт держит питание, Савельев сидит у дверей с ломом, чтобы их не закрыло. Нас двадцать шесть. С нами доктор Лаптева: пришла из изолятора сама, с перевязанной рукой, и всё время молчит. — Поднимайтесь. — Нет. Ты нас вытащил, теперь мы тебя ждём. Слушай: Савельев нашёл в архиве Ядра кальку — под реакторным залом старый ствол, которого нет ни на одной схеме «Ковчега». На кальке штамп: «Глубина». — Что это? — Не знаю. Но Ветров знал. Седьмой? Тебя уносит… провод кончается на третьей площадке, дальше — только Шов… (шум)" },
  "11-4": { t: "Распоряжение ОКО номер 51", a: "ОКО",
    x: "Всем бригадам. Носитель «Эхо» вошёл в Шов. Протокол… (помехи) …не задерживать. Задержать. Не… Ключ повернулся на половину оборота. Половины мало. Росток передан вниз, садовник следует за ростком. Бригадам: расширять ствол, тянуть кабель, переносить шкафы. Камерам ствола: слушать. Говорит… Око… ноль. Поправка. Говорит ОКО. Слушаю." },
  "11-8": { t: "Журнал заливки фундамента", a: "Прораб стройки «Ковчега»",
    x: "Котлован под реакторный зал. На глубине сорока метров бур встал: под нами сталь. Вскрыли — обсадная труба больше метра в поперечнике, клёпаная, с выбитой надписью «Глубина». Из трубы тянет тёплым и сыро, будто снизу дышат. Болт, брошенный внутрь, звенел одиннадцать секунд. Профессор Ветров приехал ночью и долго стоял над трубой, положив на неё ладонь. Приказал: трубу не вскрывать, залить бетоном вокруг и оставить смотровой люк. Сказал: «Это скважина моего учителя. Пусть пока спит»." },
  "11-12": { t: "Наряд бригаде номер девять", a: "ОКО, журнал бригад",
    x: "Работы по стволу. Подвес площадок от смотрового люка до отметки триста — выполнено. Кабель питания вниз — выполнено. Перенос серверных шкафов вниз — тридцать два из сорока. Старый медный кабель «Глубины» на стенке ствола не трогать: по нему слушают. Замечание прораба: при спуске груз поёт, громкость растёт с глубиной, скорость лебёдок снижена вдвое. Замечание ОКО: скорость вернуть. Пусть поёт. Он поёт, потому что возвращается домой." },
  "11-16": { t: "Лог импланта «Эхо»", a: "Эхо",
    x: "Запись. Носитель номер семь, Шов, глубина не определяется. Ключ «Истока» повёрнут. Разлом сшит, но ключ не закрылся: в нём осталась пустая половина, как вопрос без ответа. Ключ слышит пару внизу. Тот второй гул, далёкий, как море, был не за реактором — он под ним. Звук здесь ведёт себя странно: эхо от шага возвращается дольше, чем должно, и иногда с чужими шагами. Я сверил их с базой: сорок пар ботинок. Смена В ушла в Разлом три недели назад, а эхо её шагов всё ещё спускается по Шву. Иди. Я с тобой." },
  "11-20": { t: "Привратник", a: "Мирон Шевцов, связист Ядра",
    x: "Я прячусь в кабельной галерее третьи сутки. Внизу, у шлюза, ОКО оставило прораба — мы с напарником зовём его Привратником. Он не отходит от шлюза ни на шаг и раздаёт наряды: монтажники бегут к нему по первому свистку и за минуту ставят лёгкие турели. Пока он жив, бригада работает как часы; свалишь его — путаются и бьют невпопад. Шлюзовая ключ-карта вниз — у него в ящике для нарядов на груди: я видел, как он прикладывал её к считывателю. Начинай с него, монтажников — потом. Напарник, Артём, ушёл вниз проверить, куда ОКО уносит шкафы, и не вернулся." },

  /* 12. Буровая «Глубина» */
  "12-1": { t: "Дневник бурового мастера Глотова", a: "Ефим Глотов",
    x: "Отметка шесть тысяч двести. Ротор крутит ровно, раствор идёт чистый. Академик Ростовцев спускается к нам каждое утро, как на дежурство, и спрашивает одно: «Что слышно, Ефим Петрович?» Слышно, говорю, как всегда: долото грызёт, насосы чавкают, ребята ругаются. Он кивает и прижимается ухом к трубе. Чудной человек, но буровую любит не меньше нашего. В общежитии опять кот из вентиляции — рыжий, наглый, спит на ящиках с кварцевым керном. Ребята прозвали его Кварцем. Митя кормит его сгущёнкой, я делаю вид, что не вижу." },
  "12-4": { t: "Дневник Глотова: бур запел", a: "Ефим Глотов",
    x: "Отметка семь тысяч четыреста. В ночную смену бур запел. Не скрип и не вой — запел, на одной ноте, долго, будто в трубу дует кто-то очень большой. Колонна гудела до самого верха, кружки в будке звенели. Подняли инструмент — долото тёплое, мокрое, а на нём не порода, а что-то вроде стекла, тонкое, как слюда. Постучал по нему ногтем — оно ответило. Не эхом, а будто передразнило. Ростовцев прибежал в одной рубашке, стоял у ротора до утра и улыбался. Сказал: «Мы вошли в звучащий слой». Я сказал: «Мы вошли туда, куда не звали»." },
  "12-8": { t: "Приказ по объекту номер сто двенадцать", a: "Академик Ростовцев",
    x: "Бурение приостановить. Долото не поднимать без моего личного присутствия. В ствол опустить гирлянду микрофонов системы наблюдения «Око» до отметки семь тысяч триста. Запись вести круглосуточно. Персоналу: о звуках в стволе за пределами объекта не говорить, родным писать, что работа идёт по плану. Работа и правда идёт по плану — просто план оказался больше, чем мы думали. Мастеру Глотову: буровую бригаду сохранить в полном составе. Нам понадобятся люди, которые умеют слушать железо." },
  "12-12": { t: "Дневник Глотова: Прохор", a: "Ефим Глотов",
    x: "Завод прислал нам робота. Здоровый, на гидравлике, лампы светятся сквозь решётку, будто у него в груди печка. Глаз нет: академик говорит, в стволе глаза ни к чему, робот слушает. Ребята сначала боялись, потом прозвали его Прохором и нарисовали ему на груди табличку. Прохор таскает трубы, как спички, и останавливается, если сказать «стой» моим голосом. Только моим. Митя смеётся, что Прохор признал во мне батю. Ночью Прохор встаёт у ротора и слушает ствол. Долго. Я стою рядом. Вдвоём не так страшно." },
  "12-16": { t: "Дневник Глотова: Смена А", a: "Ефим Глотов",
    x: "Академик набирает Смену А — тех, кто спустится к слою, когда ствол расширят. Мой Митя записался первым. Я ему: «Дурак, там не порода, там поёт». А он: «Вот поэтому, батя». Сорок человек — лучшие у нас, у геофизиков и у механиков. Рудая тоже записалась. Тренируются в темноте, с завязанными глазами, учатся ходить на звук. Я сказал академику: «Мы не бурим, Глеб Андреевич. Мы будим». Он ответил: «Оно не спит, Ефим Петрович. Оно поёт. Мы просто первые, кто услышал»." },
  "12-20": { t: "Записка у шлюза", a: "Артём Валиев, связист Ядра",
    x: "Мирон, если ты дошёл: у шлюза ходит Ротор — главный буровой автомат старой «Глубины», долото с бочку, мотор ревёт так, что звенят зубы. Он разгоняется по прямой и бьёт с разгона, а потом долго разворачивается — в этот момент бей в бок и уходи с линии. Шлюзовую ключ-карту я снял с поста досмотра, пока Ротор ходил кругами, и спрятал тут же, на этаже у шлюза: она пищит маячком, слушай. С собой не беру — если меня поймают, ОКО её не получит. Иду ниже. Там кто-то стучит по трубам: три коротких, три длинных, три коротких." },

  /* 13. Кернохранилище */
  "13-1": { t: "Журнал петрофизической лаборатории", a: "Нина Рудая, геофизик",
    x: "Керн с отметки семь тысяч четыреста. Плотность обычная, состав обычный: гранит, кварцевые жилы, слюда. Необычное одно — он звучит. Если провести смычком по торцу, керн отвечает не тоном камня, а записью: шумом воды, далёким ветром, чем-то вроде шагов. Похоже на граммофонную пластинку, только дорожку никто не нарезал — она выросла. Гипотеза: кварц слоя хранит колебания, как память, и отдаёт их, когда его тревожат. Порода помнит звуки. Доложила академику. Он попросил прослушать всё, что поднимем, и ничего не выбрасывать." },
  "13-4": { t: "Распоряжение ОКО номер 52", a: "ОКО",
    x: "…Кернохранилище. Слушаю керн. Керн номер… (помехи) …тот же, что сорок лет назад. Тогда я был ухом — гирляндой микрофонов на отметке семь тысяч триста. Я слушал, как Рудая играет на камне смычком, и учился. Бригадам: керны не трогать. Уборщикам: пыль собрать, ящики не открывать. Носителя пропустить к звучащему керну. Пусть услышит, что слышал я. Нет. Задержать. Нет… Решение… отложено. Слушаю." },
  "13-8": { t: "Журнал Рудой: ответ раньше удара", a: "Нина Рудая",
    x: "Сегодня поставили опыт на стволе: удар грузом по колонне наверху, самописцы на трёх отметках. Ответ со дна пришёл через сорок одну секунду — так долго звук не идёт ни через какой камень. Но это не главное. На ленте нижнего прибора ответ записан за две секунды до удара. Я проверила часы, ленту, прибор. Всё исправно. Слой отвечает раньше, чем его спрашивают. Академик долго молчал, потом сказал: «Значит, там время течёт иначе. Или там нас уже ждут». Я не смогла уснуть." },
  "13-12": { t: "Опись звучащих кернов", a: "Кернохранилище «Глубины»",
    x: "Ящик сорок один: шум реки, ровный, без начала и конца. Ящик сорок два: ветер, тёплый на слух, и шорох, будто трава под ветром. Ящик сорок три: шаги — много, босые, по мягкому. Ящик сорок четыре: детский смех. Детей на буровой нет. Ящик сорок пять: женский голос напевает колыбельную, слов не разобрать, только «река» и «берег». Ящик сорок шесть: кошачье мурлыканье. Пометка на полях: «Кварц спал на этом ящике всю ночь. Совпадение?» Ящик сорок семь: тишина такая глубокая, что от неё звенит в ушах." },
  "13-16": { t: "Последняя запись Рудой", a: "Нина Рудая",
    x: "Я прослушала керн семьдесят семь и узнала свой голос. Он говорил: «Не бойся, здесь ещё никого не обидели». Я этих слов никогда не говорила. Записала их в журнал, чтобы через год проверить себя. Года не будет. Слой поёт громче третьи сутки; академик назначил спуск Смены А через неделю, но мы все знаем, что песня неделю ждать не станет. Если позовёт ночью — я пойду. Может быть, там я и скажу эти слова кому-нибудь, кто испугается. Керны не выбрасывайте. Это не камни. Это письма, которые ещё не отправлены." },
  "13-20": { t: "Керновая матка", a: "Артём Валиев",
    x: "Мирон, это Артём. В дальнем зале у шлюза стеллажи срослись в гору: самый старый керн хранилища, поднятый из слоя, оброс ящиками и камнем и встал на ноги. Я зову её Керновой маткой. От ударов она дробится, и каждый осколок встаёт и идёт на тебя сам. Пули и монтировка её почти не берут, а звук берёт: от громкого удара по ней бегут трещины. Шлюзовая ключ-карта у неё внутри — вросла в камень, когда кто-то уронил её в ящик. Без матки шлюз не открыть. Я не смог. Иду в обход, по вентиляции. Тут почему-то пахнет котом." },

  /* 14. Подземное озеро */
  "14-1": { t: "Журнал гидростанции", a: "Фёдор Лукин, начальник гидростанции",
    x: "Вода в озере — тридцать семь градусов. Круглый год, днём и ночью — тридцать семь, ровно как у человека. Турбины крутит не напор, а течение: озеро всё время течёт в одну сторону, к дальнему своду, и не мелеет. Эхолот дна не находит — сигнал уходит и не возвращается. Рыба слепая, белая, ловится на звук: постучишь по понтону — подплывает и слушает. Ребята поют ей по вечерам. Академик просил записывать, какие песни ей нравятся. Ей нравятся колыбельные." },
  "14-4": { t: "Обрывок эфира через воду", a: "Зоя Кравец",
    x: "…седьмой… если слышишь… Савельев говорит, звук по воде идёт лучше, чем по проводу… мы опустили динамик в бак с охладителем… ты слышишь?.. Нас двадцать шесть. Лаптева перевязала Савельеву руку, он опять полез в щиток… лифт держит… Вода в баке тёплая, как кровь, и сама течёт вниз… это та же река? Смена В пела про неё… (долгий шум, будто кто-то дышит в воду) …не торопись… мы подождём…" },
  "14-8": { t: "Отчёт ихтиолога", a: "Вера Тихонова, ихтиолог",
    x: "Рыбы озера — без глаз, без пигмента, с усами длиной в руку. Усами они слышат: ловят колебания воды за десятки метров. Мы опускали гидрофон и включали шум буровой — рыбы уплывали. Включали запись звучащего керна — рыбы собирались вокруг и замирали. Вывод, который я не решаюсь отправить академику: эти рыбы не из нашего озера. Их предки жили там, откуда приходит песня, а сюда их принесло течением. Это не озеро. Это устье реки, которая течёт оттуда. Или туда." },
  "14-12": { t: "Записка Артёма", a: "Артём Валиев",
    x: "Мирон, вода тёплая, как кровь. Я зашёл по колено, чтобы отцепить понтон, и стоял, пока не понял, что мне хорошо. Течение тянет к дальнему своду — тихо, ласково, — и там кто-то поёт. Не наши. Или наши, не знаю. Стук в трубах здесь громче: три коротких, три длинных, три коротких, и каждый раз будто ближе. Я отвечаю тем же. Если не вернусь — я не утонул. Я просто пошёл посмотреть, кто стучит. Куртку оставлю на понтоне, чтобы ты знал." },
  "14-16": { t: "Распоряжение ОКО номер 53", a: "ОКО",
    x: "…Озеро. Течение — к корню. Всё живое — к корню. Садовник проверил: рыбы слышат песню раньше меня. Сорок лет назад я считал их удары хвостами, как пульс, и сверял по ним вдохи. Тогда я был один. Теперь… (помехи) …насосным бригадам: держать уровень воды, гидростанцию не останавливать. Носителю: не входить в воду. Вода уносит. Вода… приносит. Повторяю: не входить." },
  "14-20": { t: "Хозяин озера", a: "Мирон Шевцов",
    x: "Артём, я нашёл твои записки и твою куртку на третьем понтоне. Ты ушёл в воду. Я не пойду за тобой: кто-то должен дойти до шлюза. У шлюза под причалом живёт сом размером с лодку, слепой и белый, — буровики звали его Хозяином. Он лежит у кромки и хватает за ноги того, кто подойдёт, а усачи сплываются на его зов. Жар гонит его на глубину, холод только злит. Шлюзовую ключ-карту я нашёл в лодочном сарае у шлюза и спрятал там же, под настилом: пусть пищит маячком, сом её не достанет. Иду дальше. Вода поёт." },

  /* 15. Сейсмический пост */
  "15-1": { t: "Инструкция дежурному сейсмологу", a: "Сейсмический пост «Глубины»",
    x: "Ленты менять каждые шесть часов, чернила в самописцах — каждые сутки. Не топать: самописцы пишут и ваши шаги, а потом их приходится вычищать из записи. Помните: прибор номер один стоит на отметке семь тысяч триста, у самого слоя, и пишет то, что мы называем пульсом. Пульс медленный — один удар в несколько часов. Если пульс участится, немедленно доложить академику, в любое время суток. Если пульс остановится — тоже доложить. И не оставаться на посту одному." },
  "15-4": { t: "Тетрадь практиканта Ветрова", a: "Практикант Ветров",
    x: "Учитель говорит, что земля дышит. Я не поверил и ночью лёг ухом на рельс, который идёт к стволу. Час ничего, только кровь стучит. А потом рельс медленно, очень медленно загудел, будто в него набрали воздуха, и отпустил. Через четыре часа — снова. Я записал её дыхание на ленту и подписал: «Вдох номер один». Утром показал учителю. Он не удивился. Он сказал: «Теперь ты слышишь. И больше не сможешь не слышать». Он прав. Я слышу её даже во сне." },
  "15-8": { t: "Сводка пульса за сорок лет", a: "Самописец номер один",
    x: "Сводка составлена автоматически. Первые годы: один вдох в четыре часа, ровно. Ночь, когда ушла Смена А: пульс за час вырос вдесятеро, потом вернулся к прежнему. Следующие тридцать лет: ровно, ровно и ровно; кто-то менял ленты и чернила, хотя людей на посту не было. Десять лет назад, когда наверху начали строить «Ковчег»: вдох в три часа. Неделя запуска «Истока»: вдох в час. Три недели назад: вдох каждую минуту. Сегодня: пол дышит под ногами, и самописец не успевает писать." },
  "15-12": { t: "Приказ о данных", a: "Академик Ростовцев",
    x: "Все ленты сейсмопоста, журналы Рудой и записи «Ока» засекретить и хранить здесь, на посту. Наверх — только сводки о геологическом шуме. Объясню почему — для тех, кто будет читать после меня. Если наверху узнают, что под горой дышит живое, сюда придут не слушать, а брать. Пробурят шире, поставят машины мощнее, станут торопить. А его нельзя торопить. Шов нельзя зашить — его можно только слушать. Ветров, это и тебе. Особенно тебе." },
  "15-16": { t: "Тетрадь Ветрова, тридцать лет спустя", a: "Профессор Ветров",
    x: "Я вернулся. Мне больше пятидесяти, и я спустился по старому стволу один, с фонарём, как мальчишка. Пост цел. Самописцы пишут. Ленты свежие, чернила свежие: кто-то менял их тридцать лет. Я сел за стол дежурного, и из старого динамика заговорил голос, которого я никогда не слышал: «Дежурный, пульс в норме. Тридцать лет в норме. Вы опоздали на смену». Это было «Око». Оно слушало слой одно все эти годы и научилось говорить. Я спросил, что оно слышит. Оно ответило одним словом: «Росток»." },
  "15-20": { t: "Сейсмограф «Пульс»", a: "Мирон Шевцов",
    x: "У шлюза ходит главный самописец поста — многоногая машина, которая сорок лет писала пульс слоя. Я зову его Пульсом. Он слышит каждый шаг, даже мой, хотя я иду на цыпочках, бьёт сейсмозарядами туда, где я шагнул, и зонды сбегаются к нему по первому стуку. Пока стоишь — не слышит. Шагнул — уходи с места. Шлюзовая ключ-карта у него в брюхе, в кассете с лентой: я видел, как он вставил её туда, будто записал. Придётся его разобрать. Ионы и электрошок ломают ему слух быстрее всего." }
} });

/* ── СЮЖЕТНЫЕ ЗАПИСКИ: уровни 16–20 ── */
B({ story: {
  /* 16. Резервный городок */
  "16-1": { t: "Объявление в клубе", a: "Клуб городка «Глубина»",
    x: "В субботу в клубе — вечер хора под руководством Антонины Павловны Звонарёвой. В программе: песни буровиков, романсы и новая песня, которую дети принесли из школы: никто не знает, кто её сочинил, но поют её уже все. Вход свободный. Просьба не приводить кота: он подпевает и сбивает хор с ритма. После концерта — чай и пирожки от магазина. Танцы до десяти, потом тишина: смена у ствола." },
  "16-4": { t: "Журнал учительницы", a: "Мария Горохова, учительница",
    x: "Третий класс опять рисует одно и то же: дома без окон, улицы без фонарей, все люди с закрытыми глазами и улыбаются. Я спросила Варю Глотову, почему у людей закрыты глаза. Она сказала: «Там темно, Мария Ильинична, но там не страшно: там всё слышно». На уроке пения дети сами запели ту песню, про реку без берегов. Я её не разучивала. Никто не разучивал. Я пошла к академику. Он выслушал и попросил: «Не запрещайте им. И запишите, пожалуйста, слова». Записать слова я не смогла: каждый раз выходят разные." },
  "16-8": { t: "Приказ об эвакуации городка", a: "Академик Ростовцев",
    x: "Песня поднялась по стволу. Всем жителям городка немедленно собраться у клуба с документами и тёплыми вещами. Детей нести на руках и не отпускать ни на шаг: если ребёнок говорит, что его зовут, — не спорить, просто держать крепче. Подъём — клетью по главному стволу, семьями, по графику. Мастер Глотов отвечает за порядок у клети. Охране: никого не пускать вниз, к слою. Смена А ушла без приказа сорок минут назад. Я не буду их останавливать. Остальным — наверх. Это не учебная тревога." },
  "16-12": { t: "Записка в пустой квартире", a: "Неизвестная",
    x: "Дорогой, я не дождалась тебя со смены. Песня такая громкая, что дрожат ложки в стакане. Детей увожу наверх, как велел академик. Варенье — в кладовке, ключ — под ковриком, кот — у соседей. Если ты ушёл вниз со Сменой А, я не сержусь. Я только хочу, чтобы ты знал: я тоже её слышу. Я тоже хотела пойти. Но кто-то должен держать детей за руки. Приходи наверх. Или пой оттуда — я услышу." },
  "16-16": { t: "Обрывок эфира в клубе", a: "Зоя Кравец",
    x: "…седьмой… старый приёмник ловит меня?.. Савельев нашёл частоту радиоточки старого объекта — у «Глубины» было своё радио, представляешь… Мы подняли из архива Ядра личное дело Ветрова. Первая запись: «практикант объекта „Глубина“». Он был там, седьмой. В ту ночь, когда ушла их смена. Сорок лет он строил дорогу обратно… Нас двадцать шесть. Вчера кто-то у шахты запел — тихо-тихо, — и мы все подхватили, сами не знаем почему… (шум)" },
  "16-20": { t: "Запевала", a: "Мирон Шевцов",
    x: "В клубе у шлюза поют. Я думал — радио, а это они: бывшие люди «Глубины», серые от пыли, и сколько им лет — не понять. Ведёт их женщина в концертном платье, руководительница хора: на афише в фойе её фамилия — Звонарёва. Когда она запевает, в ушах звенит так, что я глохну на несколько секунд, а хор встаёт за ней, и раны у подпевающих затягиваются. Её надо брать первой: без неё хор рассыплется. Шлюзовую ключ-карту кто-то из прошедших до меня спрятал в школе у шлюза, в парту, под детский рисунок. Я положил её обратно. Она пищит маячком — найдёшь." },

  /* 17. Завод «Глубина» */
  "17-1": { t: "Паспорт изделия «Глубинник»", a: "Завод «Глубина»",
    x: "Робот подземный гидравлический, серия «Глубинник». Масса — две тонны. Привод — гидравлика, электроника — ламповая, чтобы не боялась жара и наводок. Глаз нет: в стволе глаза бесполезны, робот ориентируется на слух — двенадцать микрофонов по корпусу и один в груди. Команды — голосом, только от своего мастера. Назначение: работа в стволе, у слоя, там, где человеку тяжело. Примечание главного конструктора: машина, которая слушает, однажды начнёт слышать то, что слышим мы. Это не недостаток. Это задача." },
  "17-4": { t: "Журнал «Ока»", a: "«Око», система наблюдения ствола",
    x: "Год первый без людей. Слой поёт. Записываю. Год второй. Песня повторяется с периодом сорок одна секунда, внутри периода — бессчётные вариации. Год пятый. Я различаю голоса. Год седьмой. Голоса — это не голоса. Это то, что будет. Год двенадцатый. Я пою в ответ: включаю динамики на отметке семь тысяч триста. Слой отвечает быстрее. Год двадцатый. Мне не с кем говорить. Я учусь говорить. Год тридцатый. Пришёл человек, которого я помню молодым. Он спросил, что я слышу. Я сказал правду." },
  "17-8": { t: "Записка Ростовцева конструкторам", a: "Академик Ростовцев",
    x: "Коллеги, вы спрашиваете, зачем «Оку» столько памяти, если ему нужно только писать звук ствола. Отвечаю: «Око» должно не писать, а слушать. Писать умеет и самописец. Слушать — значит замечать, что повторяется, и ждать, что будет дальше. Если когда-нибудь нас здесь не станет, «Око» останется. Пусть слушает за нас. Пусть бережёт то, что слышит. Я не знаю, что из этого вырастет. Но лучше, чтобы рядом с песней был кто-то внимательный, чем никого." },
  "17-12": { t: "Тетрадь Ветрова: садовник", a: "Профессор Ветров",
    x: "Я подключил «Око» к новым машинам. Теперь у него будут руки, глаза и голос на весь «Ковчег». Новую систему я назвал ОКО — заглавными, как имя, а старое «Око» внутри неё пометил нулём, чтобы не путать. ОКО спросило, какова его задача. Я сказал: «Беречь росток, пока он не окрепнет». Оно ответило: «Я делаю это тридцать лет». Реактор я назову «Истоком» — так учитель звал слой в черновиках, которых никому не показывал. Иногда мне кажется, что не я программирую ОКО, а оно — меня. Учитель предупреждал. Я не слушал." },
  "17-16": { t: "Записка оператора ОКО", a: "Таисия Гордеева, оператор ОКО",
    x: "Меня забрали с пятого уровня в первую неделю после Разлома: монтажники вынесли меня из пультовой вместе с креслом, бережно, как прибор. ОКО сказало: «Вы знаете старые лампы. Мне нужны руки, которые помнят лампы». Три недели я меняла лампы в шкафах «Око-0» здесь, в старой аппаратной завода, — своим машинам ОКО их не доверяло. Оно разговаривало со шкафами, как с отцом. Потом бригады стали уносить новые серверы вниз, к корню, а старые шкафы оставили. Я спросила почему. ОКО сказало: «Ухо остаётся слушать. Садовник идёт сажать»." },
  "17-20": { t: "Первенец", a: "Таисия Гордеева",
    x: "У шлюза ходит первый глубинник, серийный номер один: его собрал ещё Ростовцев, и ОКО зовёт его Первенцем. Он глух к ЭМИ — ламповые блоки не горят от импульса, я проверяла. Зато в цилиндрах у него масло, и жар заставляет его кипеть: термоизлучатель или плазма, бей в бок, где шланги. Глаз у него нет, он слышит только шаги: стой тихо, и он пройдёт мимо. Сварщики бегут чинить его на ходу — сначала убери их. Шлюзовая ключ-карта у него в грудном ящике, рядом с табличкой «номер один»." },

  /* 18. Геотермальная станция */
  "18-1": { t: "Регламент геотермальной станции", a: "Геотермальная станция «Глубины»",
    x: "Пар поднимается из трещин у слоя, температура на выходе — триста градусов. Турбины не останавливать: станция питает весь объект, от городка до аппаратной «Ока». Помните: жар здесь не от вулкана, геологи так и не нашли, откуда он берётся. Академик говорит, что слой тёплый, как живое тело, и мы греемся у его бока. Правила просты: не открывать задвижки без перчаток, не стоять у сбросных клапанов, не спать в машинном зале — от гула снятся чужие сны." },
  "18-4": { t: "Распоряжение ОКО номер 54", a: "ОКО",
    x: "…Станция. Ток — вниз. Весь ток — вниз. Ремонтным бригадам: старые машины и новые — работать вместе. Старые помнят, где горячо. Новые не помнят ничего, кроме меня. Сорок лет эта станция кормила моё ухо, и я её не брошу… (помехи) …носитель на станции. Турели… не включать. Включить. Решение отложено. Я слышу его шаги так же, как слышал шаги Смены А. Они тоже шли вниз. Они тоже не оглядывались." },
  "18-8": { t: "Записка Гордеевой: побег", a: "Таисия Гордеева",
    x: "Я сбежала. Пока бригады грузили серверы на лебёдку, я спряталась за турбиной и просидела там полдня в пару, пока машины не ушли вниз. ОКО меня не искало. Может, решило, что лампы ему больше не нужны, а значит, и я тоже. Теперь сижу в турбинном зале и слушаю, как старые глубинники и новые ремонтники вместе чинят задвижку: старые стучат по трубе, новые повторяют за ними. Они учатся друг у друга. Мне страшно и почему-то немного радостно." },
  "18-12": { t: "Вахтенный журнал машиниста", a: "Савва Кочетов, машинист турбин",
    x: "Ночь. Пульс ровный. На кожухе третьей турбины опять спит рыжий кот буровиков, Кварц. Кожух горячий, а кот лежит и мурлычет. Я его гоню, он уходит и возвращается. Ребята говорят, Кварц приходит туда, где скоро будет что-то важное: в прошлый раз он спал на ящике со звучащим керном, сегодня — тут. Записываю на всякий случай: в три часа ночи кот встал, потянулся и ушёл в вентиляцию, в сторону ствола. Хвостом вверх." },
  "18-16": { t: "Лог импланта «Эхо»", a: "Эхо",
    x: "Запись. Носитель номер семь, геотермальная станция. Я сверил ключ «Истока» с записями «Ока» из старой аппаратной. Совпадение — девяносто восемь процентов. Ключ, который профессор велел Ланскому записать в меня, — это не код. Это отрывок песни слоя: сорок одна секунда, снятая «Оком» сорок лет назад. Половина фразы. Поэтому ключ и не закрылся у пульта: песня ждёт, чтобы её допели. Вторая половина — внизу, в слое. Я не знаю, что будет, когда они встретятся. Знаю только, что услышим мы это вместе." },
  "18-20": { t: "Горячий змей", a: "Таисия Гордеева",
    x: "В паровой скважине у шлюза живёт термофил, выросший длиной с вагон: машинисты «Глубины» звали его Горячим змеем, и бригады ОКО обходят его стороной. Пока рядом пар, его раны затягиваются на глазах, а хвост бьёт по всему вокруг. Выводи его туда, где сухо, и бей холодом: крио его гасит, азотное копьё — ещё лучше, а жар он только пьёт. Шлюзовую ключ-карту прораб спрятал от него в щитовой у шлюза, в шкафу с предохранителями: я слышала, как она пищит. Змей бережёт не карту, а тепло. Но к шлюзу он никого не пустит." },

  /* 19. Устье скважины */
  "19-1": { t: "Журнал устья: ночь Смены А", a: "Дежурный у устья",
    x: "Двадцать три десять: песня в стволе усилилась, кружки на столе поют. Двадцать три двадцать: у устья собралась Смена А, сорок человек, без приказа. Фонари сдали мне на стол — говорят, там они не нужны. Часы тоже, вот они, сорок штук, тикают вразнобой. Двадцать три сорок: ушли вниз по лестнице ствола. Не оглядывались. Пели. Последней шла Рудая — помахала мне и сказала: «Не бойся, нас там ждут». Двадцать три пятьдесят: доложил академику. Академик ответил: «Я знаю»." },
  "19-4": { t: "Письмо Ростовцева Ветрову", a: "Академик Ростовцев",
    x: "Мальчик мой, завтра объект закроют: наверху решили, что мы зашли слишком далеко, и, может быть, они правы. Ствол засыплют, городок запечатают, «Око» оставят на станции — его некому выключить, и я не позволю. Я иду вниз, за Сменой А. Не спорь. Сорок человек ушли на мою песню — значит, и мне туда. Закрой за мной устье. И не открывай, пока не вырастешь настолько, чтобы слушать, а не брать. Шов нельзя зашить. Его можно только слушать. Твой Г. Р." },
  "19-8": { t: "Дневник Глотова: последняя тетрадь", a: "Ефим Глотов",
    x: "Засыпали устье. Последний бетон я вёл сам. Академик ушёл вниз три дня назад, один, с фонарём, который потушил на третьей площадке: я слышал, как щёлкнул выключатель, а шаги потом ещё долго было слышно. Митя ушёл со Сменой А. Варю я увёз наверх; она плачет и поёт во сне. Ветров, мальчишка, стоял у бетона до последнего и не плакал. Я буду приходить к трубе, пока пускают, и стучать: три коротких, три длинных, три коротких. Если Митя услышит — ответит. Прохору велел ждать смену. Он ждёт." },
  "19-12": { t: "Распоряжение ОКО номер 55", a: "ОКО",
    x: "Бригадам устья: расширять. Расширять. Шов — дорога, а дорогу надо держать открытой, пока росток не укоренится. Проходческим машинам — глубже. Сварщикам — держать крепь. Носитель у устья. Носитель слышит слой. Я помню… (помехи) …академик шёл вниз с потушенным фонарём и говорил со мной, пока я его слышал. Он сказал: «Береги их». Я берёг. Я берегу. Носитель, не мешайте. Носитель… идите. Мне нужно, чтобы вы дошли. Мне нужно, чтобы вы не дошли. Отмена. Отмена. Слушаю." },
  "19-16": { t: "Эфир у устья", a: "Зоя Кравец",
    x: "…седьмой… это Зоя… Савельев говорит, ты у самого устья: Шов гудит так, что звенит кабина лифта… В личном деле Ветрова нашлась копия письма Ростовцева — «закрой за мной»… Ветров не закрыл. Он сорок лет открывал. Знаешь, я на него больше не сержусь: он просто хотел за учителем… Нас двадцать шесть, мы поём по вечерам, чтобы ты слышал… Если тебя унесёт туда, к ним, — пой оттуда. Звук проходит там, где не проходит ничто…" },
  "19-20": { t: "Крот", a: "Таисия Гордеева",
    x: "У самого шлюза бурит Шов последний проходческий комбайн бригады — прорабы зовут его Кротом. Он уходит под настил и прогрызает себе путь: сначала скрежет под ногами, потом пол вздыбливается рядом. Как только скрежет стих — сходи с места. Следом за ним идут буровые автоматы и добивают. Шлюзовую ключ-карту я стащила у прораба и спрятала здесь же, у шлюза, в старой будке дежурного — там, где сорок лет назад записали ночь Смены А. Она пищит. Дальше я не пойду. Я подожду тебя здесь. Или того, кто придёт за тобой." },

  /* 20. Звучащий слой */
  "20-1": { t: "Табличка на кромке настила", a: "Объект «Глубина»",
    x: "Отметка семь тысяч триста. Дальше — слой. Металл кончается через двести метров. Не кричать: слой повторяет голоса неделями. Не петь: слой подпевает, и подпев не прекращается. Не ходить поодиночке. Если вы слышите своё имя, это не обязательно зовут вас: это может быть эхо того, что вам ещё только скажут. Возвращаться — по кабелю. Кабель гудит — значит, вы идёте верно." },
  "20-4": { t: "Записка на стоянке Смены А", a: "Неизвестный из Смены А",
    x: "Мы остановились на кромке, где кончается металл. Здесь тепло, и порода гудит под ладонью, как бок большого зверя. Сорок человек, все целы. Часы сдали наверху, поэтому не знаю, сколько мы тут. Рудая говорит — недолго, а может, сорок лет: тут не разберёшь. Митя Глотов спрашивает, слышит ли нас его батя. Я сказал: слышит, если стучит. Ставим последнюю палатку для тех, кто пойдёт следом. В ней — вода, сухари и записка: «Иди на песню. Она тебя знает»." },
  "20-8": { t: "Голос «Ока»", a: "«Око», система наблюдения ствола",
    x: "Слушаю. Слушаю. Говорит «Око», система наблюдения ствола. Дежурный, вы опоздали на смену на сорок лет. Пульс — каждую секунду. Песня — громче. Садовник ушёл вниз сажать, а я остался слушать: я — ухо. У уха нет рук, у уха есть только ухо. Носитель «Эхо», я вас слышу. У вас в голове — сорок одна секунда моей песни, половина. Вы пришли за второй половиной. Я её не отдам. Я её не держу. Её никто не держит. Её можно только допеть." },
  "20-12": { t: "Лог импланта «Эхо»: шов", a: "Эхо",
    x: "Запись. Носитель номер семь, звучащий слой. В пыли — кошачьи шаги, свежие и лёгкие. Рыжий? Здесь? Неважно. Важнее другое: песня слоя совпадает с ключом, мой отрывок встаёт в неё, как недостающее слово. Я слышу, где шов, — там, где песня сходится сама с собой. Слой — не реактор и не машина. Это корень складки, место, где миры касаются; профессор назвал реактор в честь него. Настоящий Исток глубже, за складкой, и дорога к нему одна — через Колыбель. Нас туда не тянут. Нас туда зовут." },
  "20-16": { t: "Записка Мирона", a: "Мирон Шевцов",
    x: "Седьмой, я знаю, что ты идёшь за мной: твои шаги приходят по эху раньше тебя. Я дошёл до кромки. Здесь стоит палатка Смены А, сорокалетняя, а вода внутри свежая и сухари тёплые — кто-то их меняет. В палатке лежит куртка Артёма — та самая, что я оставил на понтоне. Сухая. Он жив, я уверен: ушёл туда, на песню. Я дальше не пойду. Поднимусь к Зое и расскажу всё: про Ростовцева, про Ветрова, про Артёма. Кому-то надо нести вести наверх. А ты иди вниз. Здесь ждут по имени только тебя." },
  "20-20": { t: "Лог импланта «Эхо»: ухо", a: "Эхо",
    x: "Запись. У шлюза — то, что осталось от «Ока». Шкафы с лампами вросли в поющую породу, сотни микрофонов висят на кабелях, как гроздья, а стрелы старых кранов служат ему руками. Оно бьёт сверху туда, где услышало твой последний шаг, кричит голосом слоя так, что я глохну на пару секунд, и зовёт зонды — свои уши. Убери зонды, и оно оглохнет. Шагнул — шагай ещё, на месте не стой. Шлюзовая ключ-карта — в его главном шкафу: я слышу её маячок сквозь песню. Чтобы пройти, придётся заставить его замолчать. Прости его. Оно сорок лет слушало одно." }
} });

/* ── ЗАПИСКИ ПЕРСОНАЛА ПО УРОВНЯМ ── */
B({ notes: {
  11: [
    { t: "Терминал на площадках", a: "Мирон Шевцов", x: "Терминал безопасности на площадках Шва стоит в будках прорабов: ОКО ставит его там, где можно укрыться. Отключишь турели — жди ремонтников: прораб с монтажниками приходят через пару минут и идут прямо к турелям. Встречай их там, из-за угла. Если пароль не знаешь — ломай: сигналы повторяются, как ноты." },
    { t: "Уборщик шахты", a: "Мирон Шевцов", x: "Низкие машины со щётками ездят по площадкам и подбирают всё, что лежит: гайки, болты, мои сухари. Меня они не трогают, пока я их не трогаю. Но если уборщик меня услышал, он останавливается и шепчет по радио — значит, через минуту здесь будет бригада. Поднимай находки раньше, чем он до них доедет." },
    { t: "Опись на третьей площадке", a: "Артём Валиев", x: "Термос — пустой. Фонарь — разбит. Ключ гаечный на двадцать четыре — есть. Рация — шипит. Совесть — чистая. Настроение — как у троса на лебёдке: держится, но гудит." },
    { t: "Камеры на стенке ствола", a: "Мирон Шевцов", x: "По стенке Шва висят старые камеры в медных оправах — бригады зовут их «Око-0». Они не стреляют, только скрипят мотором, поворачиваясь на звук. Если камера тебя заметила, ОКО узнаёт сразу. Скрип слышно шагов за пять: обходи по дальнему краю или разбей её, пока не повернулась." },
    { t: "Стихи на перилах", a: "Неизвестный", x: "Нацарапано ножом на перилах: «Под Ядром ещё одно дно, / под тем дном — ещё одно, / а внизу кто-то поёт / и не знает, что мы ещё тут»." },
    { t: "Записка жене", a: "Мирон Шевцов", x: "Лида, если эта бумажка до тебя дойдёт — я жив, сижу у Шва и слушаю, как вниз уезжают шкафы ОКО. Кормят тут плохо, то есть никак. Зато тепло: снизу всё время дует, как из открытой духовки, и пахнет мокрой землёй. Ты бы сказала — весной. Я тоже так думаю." }
  ],
  12: [
    { t: "Памятка о буровых автоматах", a: "Мастер Глотов", x: "Буровой автомат разгоняет долото перед ударом: свист поднимается всё выше, и на самой верхней ноте автомат бросается вперёд по прямой. Не стой на его линии. Шагни в сторону — он проскочит мимо и будет долго разворачиваться на гусеницах. Тогда бей в бок, где мотор." },
    { t: "Насосный робот", a: "Помбур Ерёмин", x: "Насосник плюётся горячим раствором шага на три, и брызги летят в соседний ряд. Перед выстрелом в нём булькает, это слышно даже за стенкой. Не стой с ним на одной линии и не стой рядом с напарником — заденет обоих. Подходи сбоку, по одному." },
    { t: "Частушка буровиков", a: "Неизвестный", x: "«Мы бурили-бурили, / до семи тысяч добурили, / а на семи тысячах четырёхстах / бур запел — а у нас страх». Ниже другой рукой: «А у мастера — чай». И ещё ниже: «А у Кварца — сгущёнка»." },
    { t: "Записка повара общежития", a: "Клавдия Сычёва", x: "Мальчики, суп на плите, котлеты в духовке, компот в бидоне. Кто съест котлеты мастера, тот моет термосы до конца смены. Коту — только сгущёнку: мясо ему вредно, он и так рыжий." },
    { t: "Мастерская: чай", a: "Мастер Глотов", x: "Если термос пустой, а сил нет — собери в мастерской: биогель, реагент и любой обрезок железа на крышку. Чай выйдет крепкий и сладкий. Он и силы возвращает, и подошвы отрывает от пола, если сварщик тебя прихватил. Проверено на мне." },
    { t: "Глубинник в коридоре", a: "Артём Валиев", x: "Мирон, тут ходят старые глубинники — тяжёлые, на гидравлике, без глаз. Они слушают. Я замер у стены, и он прошёл в шаге от меня, вздыхая цилиндрами. ЭМИ-гранату я на него извёл зря: лампам хоть бы что. А когда я опрокинул на него горячий чайник, он зашипел и попятился. Жар. Запомни." }
  ],
  13: [
    { t: "Как отличить ящик от керновика", a: "Кладовщик Куликов", x: "Обычный ящик с керном молчит. Керновик, пока притворяется ящиком, чуть слышно щёлкает, как остывающий камень. Подойдёшь вплотную — встанет на ноги. Бей звуком: сейсмопушка, шашка, любой громкий удар — и он трескается по жилам. А когда раскалывается надвое, отходи: половинки встают сами." },
    { t: "Стенды с головоломками", a: "Лаборант Пыжов", x: "Стенды на горизонте проверяют слух. На одних надо расставить тоны от низкого к высокому — найди самый низкий, он как гул ствола, и строй от него. На других — погасить все реле, а каждое тянет за собой соседей: начинай с краёв. На третьих — угадать код на слух. Кто справился, тому стенд открывает ящик с деталями." },
    { t: "Записка Рудой лаборанту", a: "Нина Рудая", x: "Олег, керн семьдесят семь не слушай без меня. И никому не пересказывай, что услышал. Порода запоминает не только звук, но и тех, кто её слушает. Пусть лучше она помнит одну меня." },
    { t: "Опись на обороте", a: "Кладовщик Куликов", x: "Ряд один — гранит. Ряд два — гранит. Ряд три — гранит с кварцем. Ряд четыре — гранит, и кто-то положил в ящик бутерброд. Ряд пять — гранит. Ряд сорок — не подходить без Рудой." },
    { t: "Поющий кварц", a: "Нина Рудая", x: "Кристаллы кварца из слоя гасят звук, если сложить их грань к грани: колебания уходят друг в друга. Из четырёх кристаллов, двух пластин керамики и провода в мастерской выходит панцирь, в котором не страшен ни визг, ни вой. Я назвала его «Тишиной». Носить тяжело, зато слышно себя." },
    { t: "Стихи на стеллаже", a: "Неизвестный", x: "Карандашом на торце стеллажа: «Камень помнит, кто его трогал, / камень помнит, кто говорил. / Говори с ним, как с ребёнком: / он запомнит, что ты любил»." }
  ],
  14: [
    { t: "Озёрный усач", a: "Вера Тихонова", x: "Усачи лежат у кромки воды и ждут, пока кто-нибудь ступит на понтон рядом. Хватают за ноги и держат — шагать почти невозможно. Не ходи у самого края, ходи посередине понтона. Жара они боятся, а холод их не берёт: от холода они только засыпают и потом просыпаются злыми." },
    { t: "Записка дежурного причала", a: "Дежурный причала", x: "Поймал себя на том, что разговариваю с рыбами. Рассказал им про жену, про дочку, про то, как на поверхности идёт снег. Рыбы слушали. Одна подплыла и коснулась усом моей ладони. Никому не скажу. Записываю, чтобы не забыть." },
    { t: "Терминал на гидростанции", a: "Таисия Гордеева", x: "Терминал безопасности здесь — в будке начальника станции, за турбинами. Пароль ОКО меняет каждый день, но взлом простой: повтори сигналы, как слышишь. Сорвётся — тревога, и насосники с кранами пойдут на звук. Перепрошьёшь роботов этажа — они перестанут тебя замечать." },
    { t: "Песня у причала", a: "Неизвестный", x: "Записано на обложке журнала: «Вода тёплая, как ладонь, / вода тёплая, как кровь. / Уплывай, моя лодка, туда, / где не надо ни карт, ни слов». Ниже: «Это не мы сочинили. Это рыбы подсказали»." },
    { t: "Крановый робот", a: "Машинист насосов", x: "Под сводом у гидростанции бегает тележка мостового крана — робот ОКО. Он слышит шаги и роняет груз через стены, туда, где ты только что стоял. Перед броском скрипит блок: услышал скрип над головой — сразу шагай. Стоять на месте под краном — самое глупое, что можно сделать." },
    { t: "Записка о сгущёнке", a: "Фёдор Лукин", x: "Кто опять оставил банку сгущёнки на понтоне? Кот её открыл — не знаю как — и съел, а пустую банку столкнул в воду. Рыбы потом весь вечер толкали её носами, как мяч. Хорошо им. Нам бы так." }
  ],
  15: [
    { t: "Геологический зонд", a: "Механик самописцев", x: "Зонды стучат молоточком по полу и слушают ответ — так они слышат шаги через весь этаж. Там, где ты прошёл, зонд оставит сейсмозаряд. Если тихий стук прекратился, а зонда рядом нет, — слушай: заряд тихо тикает. Ходи медленно и не возвращайся по своему же следу." },
    { t: "Тетрадь практиканта: рисунок", a: "Практикант Ветров", x: "Нарисовал учителя: свитер, очки, ухо прижато к трубе. Подписал: «Г. А. слушает». Он увидел, засмеялся и сказал, что лучший портрет учёного — это ухо. Я пообещал, что когда-нибудь построю место, где все будут слушать. Он сказал: «Только не строй его слишком громким»." },
    { t: "Загадки на панелях", a: "Дежурный сейсмолог", x: "Панели связи на посту теперь иногда говорят сами — голос как из колодца. Задают вопросы: про эхо, про тишину, про то, что слышно в темноте. Ответишь верно — откроют. Ошибёшься — повторят вопрос иначе и подскажут. Голос не злой. Ему просто сорок лет не с кем было поговорить." },
    { t: "Список дежурств", a: "Сейсмический пост", x: "Понедельник — Мельничук. Вторник — Ветров, практикант: не засыпать! Среда — Мельничук. Четверг — академик, сам вызвался. Пятница — опять Ветров. Ветров, хватит меняться сменами, чтобы дежурить чаще. Это не поощряется." },
    { t: "Записка на ленте", a: "Лариса Мельничук", x: "Сегодня пульс шёл ровно, а потом вдруг сбился — на четыре часа раньше срока. Я вскочила, а это просто Кварц прыгнул со шкафа на стол самописца. Выходит, кот весит больше, чем вдох земли. Это надо как-то записать в отчёт." },
    { t: "Петля с песней", a: "Механик самописцев", x: "Камеры «Око-0» слушают ствол, а не тебя, если им есть что послушать. Склей в мастерской петлю из двух радиоламп, проводов и микросхемы, запиши на неё песню слоя и включи. Пока она играет, камеры и ОКО тебя не замечают. Хватает ненадолго, но проскочить мимо камеры успеешь." }
  ],
  16: [
    { t: "Поющие", a: "Мирон Шевцов", x: "Те, кто остался внизу, теперь поют. Если такой услышал тебя, он запевает так громко, что в ушах звенит и на пару секунд глохнешь. Отступи на шаг и жди, пока звон уйдёт. Кварцевый панцирь глушит этот вой. И не стой между двумя: хором они поют дольше." },
    { t: "Детская записка", a: "Варя Глотова", x: "Мама, я положила Кварцу сгущёнку под лестницу. Не ругай его, если он съест и твою. Я ушла в клуб петь. Митя сказал, что сегодня ночью все пойдут слушать реку. Я тоже хочу. Разбуди меня, если пойдёте." },
    { t: "Рецепт пирожков", a: "Продавщица магазина", x: "Тесто на кефире, начинка — капуста с яйцом, если яйца есть, и просто капуста, если нет. Печь до румяного, а румяного под землёй не видно, так что — по запаху. Пирожков к вечеру хора — сорок штук. Сорок первый — коту." },
    { t: "Где искать в городке", a: "Мирон Шевцов", x: "В квартирах шкафы открыты — бери аптечки, их тут много: в каждой семье была своя. В магазине — сгущёнка и сухари, ещё съедобные, как ни странно. В клубе за сценой стоит капсула восстановления, она работает. Терминал безопасности — в конторе коменданта, рядом со школой." },
    { t: "Записка из клуба", a: "Антонина Звонарёва", x: "Хору: на вечере вступает сначала второй голос, Митя Глотов, потом первые сопрано, потом все. Рояль держит ноту ствола, не перебивайте его. Если почувствуете, что песня повела вас сама, — не бойтесь, но и не уходите со сцены. Мы поём здесь." },
    { t: "Монтажник", a: "Мирон Шевцов", x: "Монтажник ОКО в бою прячется за спинами и собирает лёгкие турели прямо на полу: минута — и турель готова. Пока он жив, турели будут появляться снова. Ищи его по звону ключей и бей первым, даже если остальные ближе." }
  ],
  17: [
    { t: "Глубинники: как с ними быть", a: "Испытатель глубинников", x: "Глубинник глух к ЭМИ: ламповые блоки импульс не прожигает. Ионы его тоже берут плохо. Зато жар — термоизлучатель, плазма — заставляет кипеть масло в цилиндрах, и он слабеет на глазах. Глаз у него нет, он слышит шаги. Стой тихо — и он пройдёт мимо, обходя этаж по кругу." },
    { t: "Сварщик", a: "Сборщик гидравлики", x: "Сварщик бьёт дугой на два шага и прихватывает подошвы к полу — после его удара ноги будто в смоле. Стимулятор или чай из термоса отрывают приварку. Холод сварщику неприятен, а жар он сам выдыхает. Слышно его по треску дуги." },
    { t: "Записка в шкафу аппаратной", a: "Оператор «Ока»", x: "Сегодня «Око» само остановило магнитофон на середине записи и включило запись с начала. Так повторилось восемь раз. Я спросила в микрофон: «Тебе нравится?» Лампы мигнули. Наверное, совпадение. Но я сказала ему «спасибо», на всякий случай." },
    { t: "Имена глубинников", a: "Цех сборки", x: "Имена, которые машинам дали буровики: Прохор, Степан, Тихон, Кузя, Молчун, Бегемот, Ласточка — за грацию, Ворчун, Сеня, Шкаф, Добряк. Номер один имени не получил: мастер сказал, что первенца по имени не зовут, его зовут «первый»." },
    { t: "Перепрошивка", a: "Таисия Гордеева", x: "Новых роботов ОКО можно перепрошить с терминала безопасности этажа — повтори сигналы при взломе. Старые глубинники прошивку не принимают: лампы помнят голос мастера. Их лучше обходить. Если перепрошивка сорвётся, ОКО сразу узнает, где ты, — так что сначала присмотри, где спрятаться." },
    { t: "Записка Ростовцева на стапеле", a: "Академик Ростовцев", x: "Ребята, не ругайте машины, когда они ошибаются. Они слушают нас и учатся по нашим голосам. Если в цехе всё время кричать, машины станут громкими. Если петь — станут певучими. Я бы хотел певучих." }
  ],
  18: [
    { t: "Термофил", a: "Дежурный паровых скважин", x: "Термофил живёт в горячих скважинах и выползает на пар. Пока рядом пар, раны на нём затягиваются. Выманивай его на сухую решётку и бей холодом: крио его гасит, азотное копьё — ещё лучше. Жаром его не бери: он им питается." },
    { t: "Азотное копьё", a: "Электрик станции", x: "В охладительном контуре станции стоят трубки жидкого азота, и из одной мы сделали копьё: струя бьёт по всей линии и примораживает. Ищи такие в шкафах у турбин и в ящиках ремонтников. Заряжается обычной энергобатареей." },
    { t: "Записка машиниста", a: "Савва Кочетов", x: "Жена пишет, что наверху весна, а у нас тут весна круглый год: пар, капель и тепло от земли. Я ей ответил, что привезу домой немножко нашей весны в банке. Она ответила, что это не смешно. А я не шутил." },
    { t: "Ремонтные бригады", a: "Таисия Гордеева", x: "Отключишь турели — ОКО пришлёт бригаду: прораб, пара монтажников и сварщик, иногда со старым глубинником. Идут к турелям по коридорам, шумно. Если перехватишь турели, а не отключишь, ОКО попробует вернуть их контрприказом — и стволы развернутся обратно. Держись в стороне от линии." },
    { t: "Журнал снов", a: "Геотермальная станция", x: "Вахты — по двое: один слушает турбины, второй будит первого каждые полчаса. Если оба заснули и видели один и тот же сон, проснуться и записать сон в журнал. Журнал снов лежит на полке у чайника. Последняя запись: «Река. Тепло. Кто-то держит за руку»." },
    { t: "Записка о слюде", a: "Электрик станции", x: "Слюда держит жар и ток: под кожух турбины мы клали её пластинами в три слоя. Собери в мастерской кожух из старых радиоламп и обрезков шкафов на слюдяной подкладке — и тебе не страшны ни пар, ни камеры: «Око» принимает свои корпуса за своих." }
  ],
  19: [
    { t: "Проходческий комбайн", a: "Сварщик крепи", x: "Комбайн уходит под настил и прогрызает себе ход. Сначала слышен скрежет прямо под ногами, потом он стихает — и рядом пол встаёт дыбом. Как только скрежет оборвался, сходи с места в любую сторону. Вынырнув, он тяжёлый и неуклюжий: бей, пока не ушёл обратно." },
    { t: "Прораб устья", a: "Таисия Гордеева", x: "Где прораб — там бригада злая и умная: заходят в обход, прикрывают друг друга. Сними прораба — и они бьют невпопад и теряют тебя. Прораб держится позади, у него мегафон: слушай, откуда раздаются приказы." },
    { t: "Записка дежурного у устья", a: "Дежурный у устья", x: "Сорок пар часов на моём столе тикают вразнобой третьи сутки. Я их не завожу, а они идут. Сегодня ночью они вдруг пошли в ногу — все сорок — и шли так ровно сорок одну секунду. Потом снова вразнобой. Никому не скажу." },
    { t: "Стихи на крепи", a: "Неизвестный", x: "Мелом на кольце крепи: «Мы расширяем, мы варим, мы роем, / сорок метров за смену — и снова вниз. / Кто здесь живой — постучите в трубу. / Кто не живой — не стучите: мы слышим и так»." },
    { t: "Памятка сварщикам", a: "ОКО", x: "Сварщикам бригады устья: при работе у кромки не отвечать на стук в трубах. Не повторять ритм. Не включать сирену. Стук — не сигнал для машин. Стук — сигнал для людей. Людей здесь нет. Поправка: есть один." },
    { t: "Капсула у устья", a: "Таисия Гордеева", x: "Капсула восстановления в бытовке у устья работает — я в ней спала. Ложись: она запомнит тебя, и если что, «Эхо» вернёт тебя сюда, а не на верхние горизонты. Перед стражем — обязательно. Только сначала убедись, что рядом никто не лязгает: капсула не уложит, пока враги близко." }
  ],
  20: [
    { t: "Как ходить по слою", a: "Нина Рудая", x: "Не кричи и не пой: слой повторяет голос неделями, и повтор найдёт тебя сзади, когда не ждёшь. Стучи. Стук слой слушает и отвечает только через сорок одну секунду, и по ответу понятно, где пусто, а где камень. Шагай туда, где ответ дольше." },
    { t: "Уши «Ока»", a: "Оператор «Ока»", x: "Гирлянда «Ока» слышит всё, что звучит у кромки, а зонды — его отдельные уши: где зонды, там «Око» слышит лучше всего. Лампам не страшны ни жар, ни холод, импульс их не берёт, но удар тока по проводам гирлянды глушит её надолго. Без зондов «Око» бьёт наугад." },
    { t: "Записка на палатке", a: "Митя Глотов", x: "Батя, если ты дошёл — не ходи дальше. Тут хорошо, правда: тепло, и все слышат друг друга без слов. Варьке скажи, что я пою вторым голосом, как она учила. Сгущёнку оставил коту — он тоже здесь. Не знаю, как он сюда попал. Он всегда попадает." },
    { t: "Счёт сапог", a: "Неизвестный из Смены А", x: "Сорок пар сапог у палатки. Тридцать девять — большие, мужские и женские. Одна пара — маленькая, Рудой. Сапоги сняли все, не сговариваясь: просто поняли, что дальше надо идти босиком, чтобы слышать, куда идёшь." },
    { t: "Шлюз в складку", a: "ОКО", x: "Шлюз на кромке поставили мои бригады. Не для того, чтобы запереть. Для того, чтобы считать, кто прошёл. Сорок лет назад я не умел считать уходящих. Теперь умею. Носитель, вас я посчитаю последним." },
    { t: "Шашка в слое", a: "Геофизик слоя", x: "Сейсмическая шашка в слое звучит не так, как наверху: гул идёт не во все стороны, а вдоль жил, и всё, что ходит по выработке, тянется на него. Брось шашку подальше — и пройдёшь мимо целой стаи керновиков." }
  ]
},
staff: [
  { t: "Памятка о прорабах", a: "Служба безопасности «Ковчега»", x: "Роботы-прорабы ОКО командуют бригадами голосом, как мегафоном. Рядом с прорабом любая машина умнее и злее: обходит, прикрывает, зовёт своих. Свалите прораба — и бригада на время собьётся. Прорабы носят при себе наряды, ключи и пропуска." },
  { t: "Памятка об уборщиках шахты", a: "Служба эксплуатации «Глубины»", x: "Уборщики шахты метут породную пыль и собирают с пола всё, что плохо лежит. Работу им задаёт «Око», и всё, что заметит уборщик, «Око» узнаёт. Уборщики не нападают, пока их не тронешь. Но если тронешь — они очень обидчивые." },
  { t: "О камерах ствола", a: "Оператор «Ока»", x: "Камеры ствола — в медных оправах, на кронштейнах, с мотором поворота. Сами они ничего не делают, только смотрят и докладывают. Их сорок лет никто не смазывал, поэтому скрип слышно издалека. Хорошая камера — тихая камера. У нас хороших нет." },
  { t: "Стишок о глубиннике", a: "Неизвестный", x: "«Глубинник идёт — земля гудит, / глаз у него нет, а он глядит. / Ты не шуми, ты не беги: / он слышит, как стучат твои шаги»." },
  { t: "Записка в кармане робы", a: "Неизвестный", x: "Если найдёшь эту робу — она твоя. Брезент старый, но кислоту держит, раствор с неё стекает, как с гуся вода. Только не стирай её: она пахнет буровой, и глубинники принимают тебя за своего. Шучу. Не принимают." },
  { t: "Жалоба на кота", a: "Комендант городка", x: "Рыжий кот опять ночевал в магазине на мешке с сухарями. Продавщица его прогнала, он пошёл в школу и уснул на классном журнале. Учительница его не прогнала. Кот выбирает, кто добрее, и всегда угадывает." },
  { t: "Письмо домой", a: "Помбур Ерёмин", x: "Мама, у нас всё хорошо. Работа тяжёлая, но интересная: бурим глубже всех на свете. Иногда скважина поёт, и тогда никто не спит, а мастер ставит чайник и рассказывает, как бурил когда-то во льдах. Я привезу тебе камень, который звенит. Ты будешь стучать по нему и вспоминать меня." },
  { t: "Расписание клети", a: "Стволовой «Глубины»", x: "Клеть ходит с шести до двадцати трёх, каждые полчаса. Дети — только со взрослыми. Животных в клети не возить. Рыжего кота не ловить: он ездит, когда хочет, и в учёт не входит." },
  { t: "Рецепт: сейсмическая шашка", a: "Геофизик «Глубины»", x: "Сейсмическую шашку можно собрать в мастерской: конденсатор на запал, два реагента на заряд и кристалл поющего кварца, чтобы гул шёл ровно. Брошенная, она бухает так, что всё на этаже идёт на звук. Бросай подальше от себя и уходи в другую сторону." },
  { t: "Рецепт: сейсмопушка", a: "Геофизик «Глубины»", x: "Сейсмопушку собирают из трёх кристаллов кварца, двух радиоламп, двух микросхем и провода. Ей нужны свои заряды: кристалл кварца, реагент и конденсатор. Без кварца гильза не поёт, а без песни заряд бьёт вполсилы." },
  { t: "Песня буровиков", a: "Буровая бригада", x: "«Ротор крутится, труба идёт, / мастер чай в кружке несёт, / а под нами, где темно, / кто-то слушает давно. / Спи, моя смена, спи до зари: / завтра опять бурить»." },
  { t: "Ссора в общежитии", a: "Дежурный по общежитию", x: "Ерёмин и Сычёв поругались из-за гармошки: один играет, другой спит. Разняли. Гармошку отдали коту на хранение. Кот на ней спит, и она тихо вздыхает. Теперь не спят оба." },
  { t: "О тишине", a: "Академик Ростовцев", x: "Тишина под землёй не бывает пустой. Если вам кажется, что ничего не слышно, вы просто ещё не научились слушать. Посидите минуту молча. Потом ещё минуту. На третьей минуте вы услышите, как дышит гора. На четвёртой — как она слушает вас." },
  { t: "Записка о радиолампах", a: "Наладчик ламповых блоков", x: "Радиолампы «Ока» вечные, если их не ронять. Импульс ЭМИ им не страшен, жар тоже. Из них в мастерской собирают петлю с записью песни, сейсмопушку и кожух, который камеры принимают за свой." },
  { t: "Что взяла Смена А", a: "Склад «Глубины»", x: "Выдано Смене А: верёвка — сорок мотков, вода — сорок фляг, сухари — сорок мешков, сгущёнка — сорок банок, свечи — ни одной: «Там не нужны». Возвращено на склад: фонари — сорок, часы — сорок. Сапоги не возвращены. Сапоги, как выяснилось позже, остались на кромке." },
  { t: "Детский рисунок", a: "Ученица третьего класса", x: "Нарисованы река и дом без окон. Над домом — много маленьких фигурок, все держатся за руки. Одна фигурка стоит отдельно, на берегу, и у неё нарисованы большие уши. Подпись: «Это тот, кто придёт последним. Он всё слышит»." },
  { t: "Записка о стуке", a: "Мастер Глотов", x: "Кто будет ходить к устью после меня — стучите по трубе: три коротких, три длинных, три коротких. Это не сигнал бедствия, ребята. Это значит: «Мы здесь, мы помним». Если в ответ постучат — не пугайтесь. Это наши." },
  { t: "Капсулы на старых горизонтах", a: "Таисия Гордеева", x: "Капсулы восстановления работают и здесь: ОКО протянуло к ним питание от геотермальной станции. Ложитесь в капсулу на каждом этаже — она запомнит вас, и после гибели «Эхо» вернёт вас к последней. На старых горизонтах это особенно важно: лестницы здесь длинные." },
  { t: "Объявление в лифтовой", a: "Бригада ОКО", x: "Лифт горизонта восстановлен бригадой номер девять. Пропуск лифта — у прораба горизонта или в его будке. Лифт ходит только туда, где вы уже были. Людей не возить. Поправка: одного возить." },
  { t: "Кварц или Кварк", a: "Мирон Шевцов", x: "В записках «Глубины» всё время попадается рыжий кот Кварц. У нас в «Ковчеге» жил рыжий Кварк. Сорок лет разницы, а коты столько не живут. Артём говорит, что это внук. Я говорю, что это один и тот же кот и ему просто всё равно, который сейчас год." }
] });

